def flush(batch):
    for cid,(pt,bs,cf,tr) in batch.items():
        obj={"case_id":cid,"prediction_text":pt,"basis":bs,"confidence":cf,"trigger":tr}
        p=os.path.join(BASE,cid+".json")
        assert not os.path.exists(p), p
        with open(p,"w",encoding="utf-8") as f: json.dump(obj,f,ensure_ascii=False,indent=1)
        with open(p,encoding="utf-8") as f: d=json.load(f)
        assert d["case_id"]==cid and set(d)=={"case_id","prediction_text","basis","confidence","trigger"}
        assert 0<=d["confidence"]<=1 and all(isinstance(v,bool) for k,v in d["trigger"].items() if k!="reason")
    print("flushed",len(batch))
flush(DATA); DATA.clear()
